import * as THREE from 'three';
import {clone} from 'three/addons/utils/SkeletonUtils.js';
import {STORY,INITIAL_STORY_STATE,NPCS,ITEMS,CHAPTERS,DIALOGUES,RHYTHM_GAME,PHOTO_STYLES,PHOTO_SPOTS,ENDINGS} from './story_data.js?v=4';

const $=id=>document.getElementById(id),SAVE='qingri_campus_story_v2';
const el=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;};
export function createStory(api){
 const {scene,player,npc,toast,openDialog}=api;
 let state=structuredClone(INITIAL_STORY_STATE),stored;
 try{stored=JSON.parse(localStorage.getItem(SAVE));if(stored?.version===2&&STORY.chapterOrder.includes(stored.story?.chapterId)){state={...state,...stored.story};state.collectedItemIds=[...new Set(state.collectedItemIds.filter(id=>ITEMS.some(i=>i.id===id)))];api.restore(stored);}}catch{}
 const actors=[],pages=[],mixers=[];let near=null,photo=null,round=null,time=0,lastSave=0;
 function save(){try{localStorage.setItem(SAVE,JSON.stringify({version:2,story:state,...api.snapshot(),mapVersion:4}));}catch{toast('当前浏览器无法保存进度，请保持页面打开。');}}
 const mat=(color)=>new THREE.MeshStandardMaterial({color,roughness:.7});
 function mesh(geo,color,parent,pos){const m=new THREE.Mesh(geo,mat(color));m.position.set(...pos);m.castShadow=true;parent.add(m);return m;}
 function nameLabel(name,color){const c=document.createElement('canvas');c.width=384;c.height=96;const g=c.getContext('2d');g.fillStyle='#fffdf5ed';g.beginPath();g.roundRect(2,2,380,90,28);g.fill();g.fillStyle=color;g.font='bold 42px Microsoft YaHei';g.textAlign='center';g.fillText(name,192,61);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;const s=new THREE.Sprite(new THREE.SpriteMaterial({map:t,depthTest:true,transparent:true}));s.scale.set(3.4,.85,1);s.position.y=4;return s;}
 for(const data of NPCS){const root=new THREE.Group(),body=clone(npc.scene);root.add(body);scene.add(root);body.traverse(o=>{if(o.isMesh){o.castShadow=o.receiveShadow=true;o.frustumCulled=false;}});const mix=new THREE.AnimationMixer(body);if(npc.animations.length)mix.clipAction(npc.animations[0]).play();mixers.push(mix);const label=nameLabel(data.name,data.color);root.add(label);
  if(data.id==='tang_yu'){mesh(new THREE.BoxGeometry(.6,.4,.27),'#293638',root,[0,1.4,.5]);const lens=mesh(new THREE.CylinderGeometry(.16,.16,.18,20),'#172c3a',root,[0,1.4,.69]);lens.rotation.x=Math.PI/2;}
  else if(data.id==='zhou_yu')mesh(new THREE.SphereGeometry(.31,20,12),'#c67936',root,[.68,1.18,.15]);
  else{const roll=mesh(new THREE.CylinderGeometry(.13,.13,.95,14),'#f0d5a1',root,[.62,1.25,.15]);roll.rotation.z=.2;}
  actors.push({data,root,body,label});
 }
 for(const data of ITEMS){const g=new THREE.Group();g.position.set(data.position.x,.45,data.position.z);const sheet=mesh(new THREE.BoxGeometry(.7,.035,.9),'#fff4cf',g,[0,0,0]);sheet.rotation.y=.3;for(let j=0;j<4;j++)mesh(new THREE.BoxGeometry(.4,.012,.025),'#689185',g,[0,.03,-.25+j*.13]);const ring=new THREE.Mesh(new THREE.RingGeometry(.65,.76,32),new THREE.MeshBasicMaterial({color:'#f5be65',side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=-.36;g.add(ring);scene.add(g);pages.push({data,g,sheet});}
 // A visible ball arc and hoop make the timing interaction part of the world.
 const hoop=new THREE.Group();hoop.position.set(78,0,31);scene.add(hoop);mesh(new THREE.CylinderGeometry(.09,.12,4.3,12),'#5c7471',hoop,[0,2.15,0]);mesh(new THREE.BoxGeometry(2,1.25,.13),'#fff2da',hoop,[0,4.15,.1]);const rim=mesh(new THREE.TorusGeometry(.48,.055,8,28),'#d37845',hoop,[0,3.65,.75]);rim.rotation.x=Math.PI/2;const net=mesh(new THREE.CylinderGeometry(.45,.3,.6,12,2,true),'#fff3d4',hoop,[0,3.3,.75]);net.material.wireframe=true;
 const ball=mesh(new THREE.SphereGeometry(.24,20,12),'#d48b43',scene,[74,1.8,35]);ball.visible=false;
 function chapter(){return CHAPTERS.find(c=>c.id===state.chapterId);}
 function expand(s){return s.replaceAll('{foundPages}',state.collectedItemIds.length).replaceAll('{rhythmScore}',state.lastRhythmScore??0);}
 function sync(){for(const a of actors){const p=a.data.positions[state.completed?'complete':state.chapterId];a.root.position.set(p.x,api.ground(p.x,p.z),p.z);}for(const p of pages)p.g.visible=state.chapterId==='pages'&&!state.collectedItemIds.includes(p.data.id);const c=chapter();$('chapterLabel').textContent=state.completed?'春日校园祭 / 完结':`第 ${c.number} 章 / 共 5 章`;$('storyTitle').textContent=state.completed?'这个下午，有我们。':c.title;$('storyObjective').textContent=state.completed?'自由漫游、重试投篮，或收齐校园八景。':c.objective;$('storyProgress').textContent=state.completed?'✓ 策划页 · 试玩记录 · 两张照片':expand(c.progressLabel);}
 function target(){if(state.completed)return null;const c=chapter();if(c.id==='pages'){const item=ITEMS.find(i=>!state.collectedItemIds.includes(i.id));if(item)return {...item.position,label:item.name};const a=actors[1];return {x:a.root.position.x,z:a.root.position.z,label:a.data.name};}return c.target;}
 function event(name){const c=chapter();state.flags[name]=true;if(c.completionEvent===name&&c.next){state.chapterId=c.next;toast(c.completeText);sync();}save();}
 function showDialogue(id){const d=DIALOGUES[id];if(!d)return;const who=NPCS.find(n=>n.id===d.speaker);$('speakerInitial').textContent=who.name[0];$('speakerInitial').style.background=who.color;$('speakerName').textContent=who.name;$('speakerRole').textContent=who.role;$('dialogTitle').textContent=d.title;$('dialogText').replaceChildren(...d.lines.map(t=>el('p',expand(t))));$('dialogChoices').replaceChildren(...d.choices.map((choice,i)=>{const b=el('button',`${i+1}. ${choice.label}`);b.onclick=()=>{$('dialogText').replaceChildren(el('p',expand(choice.response)));const next=el('button','继续 →','primary');next.onclick=()=>{$('storyDialog').close();apply(choice.effect);};$('dialogChoices').replaceChildren(next);};return b;}));openDialog('storyDialog');}
 function apply(effect){if(!effect)return;switch(effect.event){case 'start_rhythm':case 'replay_rhythm':startRhythm();break;case 'open_photo':state.photoStyle=effect.photoStyle;startPhoto(false);break;case 'finish_story':state.endingChoice=effect.endingChoice;startPhoto(true);break;case 'show_ending':showEnding();break;default:event(effect.event);}}
 function interact(){if(!near)return false;if(near.type==='page'){const p=near.value;if(state.collectedItemIds.includes(p.data.id))return false;state.collectedItemIds.push(p.data.id);toast(p.data.pickupText);sync();save();journal();return true;}const a=near.value;let id=a.data.dialogues[state.completed?'complete':state.chapterId];if(a.data.id==='tang_yu'&&state.chapterId==='pages'&&ITEMS.every(i=>state.collectedItemIds.includes(i.id)))id='tang_pages_ready';a.root.lookAt(player.position.x,a.root.position.y,player.position.z);showDialogue(id);return true;}
 function journal(){const c=chapter(),body=$('journalBody');body.replaceChildren(el('p',state.completed?'故事已完成。照片和文字都收在这里。':`${c.number} / 5 · ${c.title}`,'journal-intro'));const list=el('ol','', 'chapter-list');CHAPTERS.forEach(ch=>{const li=el('li',ch.title);li.className=STORY.chapterOrder.indexOf(ch.id)<STORY.chapterOrder.indexOf(state.chapterId)||state.completed?'done':ch.id===state.chapterId?'current':'';list.append(li);});body.append(list,el('h3','散落的策划页'));for(const i of ITEMS){const got=state.collectedItemIds.includes(i.id),d=document.createElement('details');d.append(el('summary',(got?'✓ ':'◇ ')+i.name),el('p',got?i.text:i.clue));body.append(d);}body.append(el('h3','今天的搭档'),el('p',NPCS.map(n=>`${n.name} · ${n.role}`).join('　/　')));if(state.rhythmBest!==null)body.append(el('p',`投篮最好成绩：${state.rhythmBest} / 3 · 三次尝试已经完成。`));if(state.springPhoto){const img=el('img','');img.src=state.springPhoto;img.alt='樱花树旁拍下的游戏照片';body.append(img,el('p',PHOTO_STYLES.find(s=>s.id===state.photoStyle)?.caption||''));}if(state.completed){const b=el('button','打开校园祭纪念卡','primary');b.onclick=()=>{$('journalDialog').close();showEnding();};body.append(b);}}
 $('journalBtn').onclick=()=>{journal();openDialog('journalDialog');};$('trackStory').onclick=()=>{const t=target();if(t)toast(`${t.label} · ${chapter().hint}`);};
 let resetArmed=false;$('resetStoryBtn').onclick=()=>{if(!resetArmed){resetArmed=true;$('resetStoryBtn').textContent='确认重新开始？再次点击（印章会保留）';setTimeout(()=>{resetArmed=false;$('resetStoryBtn').textContent='重新开始这个故事';},5000);return;}state=structuredClone(INITIAL_STORY_STATE);sync();save();journal();$('journalDialog').close();toast('故事重新开始，去校门口找嘉豪吧。');};
 function startRhythm(){round={shots:[],clock:0,wait:0,cursor:.5};$('rhythmResult').hidden=true;$('shootBtn').hidden=false;$('shootBtn').disabled=false;$('rhythmText').textContent=RHYTHM_GAME.instructions+' 按空格也可以。';$('shotDots').textContent='○  ○  ○';openDialog('rhythmDialog');}
 function shoot(){if(!round||round.wait>0||round.shots.length===3)return;const good=round.cursor>=.38&&round.cursor<=.62;round.shots.push(good);round.wait=1.25;round.flight=0;round.good=good;ball.visible=true;$('shootBtn').disabled=true;$('shotDots').textContent=Array.from({length:3},(_,i)=>i<round.shots.length?(round.shots[i]?'●':'×'):'○').join('   ');$('rhythmText').textContent=good?'漂亮！这个节奏刚刚好。':'差一点，下一次还有机会。';}
 $('shootBtn').onclick=shoot;
 function rhythmDone(){const score=round.shots.filter(Boolean).length;state.lastRhythmScore=score;state.rhythmBest=Math.max(state.rhythmBest??0,score);event('rhythm_completed');$('shootBtn').hidden=true;$('rhythmResult').hidden=false;const b=el('button','收下试玩记录 →','primary');b.onclick=()=>{$('rhythmDialog').close();showDialogue('zhou_result');};$('rhythmResult').replaceChildren(el('p',RHYTHM_GAME.feedbackByScore[score].text),b);}
 $('rhythmDialog').addEventListener('close',()=>{round=null;ball.visible=false;});
 function startPhoto(finale){const p=finale?PHOTO_SPOTS.finale:PHOTO_SPOTS.cherry;photo={finale,original:player.position.clone(),rotation:api.hero.rotation.y,actors:actors.map(a=>({position:a.root.position.clone(),rotation:a.root.rotation.y})),camera:new THREE.Vector3(p.x,4.4,p.z+(finale?12:10)),target:new THREE.Vector3(p.x,2.1,p.z)};player.position.set(p.x-(finale?2.7:1),api.ground(p.x-(finale?2.7:1),p.z),p.z);api.hero.rotation.y=Math.atan2(photo.camera.x-player.position.x,photo.camera.z-player.position.z);if(finale){actors.forEach((a,i)=>{a.root.position.set(p.x-.9+i*1.8,api.ground(p.x-.9+i*1.8,p.z),p.z);a.root.lookAt(photo.camera.x,a.root.position.y,photo.camera.z);});}else{actors[1].root.position.set(p.x+1,api.ground(p.x+1,p.z),p.z);actors[1].root.lookAt(photo.camera.x,actors[1].root.position.y,photo.camera.z);}$('photoCaption').textContent=finale?ENDINGS[state.endingChoice].photoCaption:PHOTO_STYLES.find(s=>s.id===state.photoStyle).caption;document.body.classList.add('photo-mode');openDialog('photoDialog');}
 function cancelPhoto(){if(!photo)return;player.position.copy(photo.original);api.hero.rotation.y=photo.rotation;actors.forEach((a,i)=>{a.root.position.copy(photo.actors[i].position);a.root.rotation.y=photo.actors[i].rotation;});photo=null;document.body.classList.remove('photo-mode');}
 $('photoCancel').onclick=()=>$('photoDialog').close();$('photoDialog').addEventListener('close',cancelPhoto);
 $('photoConfirm').onclick=()=>{if(!photo)return;const finale=photo.finale,img=api.capture();cancelPhoto();$('photoDialog').close();$('photoFlash').classList.add('flash');setTimeout(()=>$('photoFlash').classList.remove('flash'),500);if(finale){state.groupPhoto=img;state.completed=true;event('story_completed');sync();save();showEnding();}else{state.springPhoto=img;event('photo_confirmed');toast('照片已收进手账。去筹备点，给今天一个开场吧。');}};
 function showEnding(){const e=ENDINGS[state.endingChoice||'together'];$('endingPhoto').src=state.groupPhoto||state.springPhoto||'';$('endingTitle').textContent=e.title;$('endingText').textContent=e.opening;$('endingLines').replaceChildren(...e.finalLines.map(t=>el('p',t)));$('endingBadge').textContent=e.evaluation;openDialog('endingDialog');}
 addEventListener('keydown',e=>{if(e.repeat)return;if(e.code==='KeyJ'&&api.started()){if($('journalDialog').open)$('journalDialog').close();else if(!document.querySelector('dialog[open]'))$('journalBtn').click();}if(e.code==='Space'&&$('rhythmDialog').open){e.preventDefault();shoot();}});
 sync();
 return {interact,save,target,
  get near(){return near;},get photographing(){return !!photo;},get cameraPose(){if(photo)return photo;if(round)return {camera:new THREE.Vector3(73,6,44),target:new THREE.Vector3(78,3,31)};return null;},
  update(dt){time+=dt;lastSave+=dt;mixers.forEach(m=>m.update(dt));for(const p of pages){p.sheet.position.y=Math.sin(time*2)*.09;p.sheet.rotation.y+=dt*.2;}near=null;let best=4.1;for(const a of actors){const d=a.root.position.distanceTo(player.position);a.label.visible=d<28&&!photo;if(d<best){best=d;near={type:'npc',value:a,label:a.data.name,action:'交谈'};}}for(const p of pages){const d=p.g.position.distanceTo(player.position);if(p.g.visible&&d<best){best=d;near={type:'page',value:p,label:p.data.name,action:'收好策划页'};}}const t=target();$('storyDistance').textContent=t?`${Math.round(Math.hypot(t.x-player.position.x,t.z-player.position.z))} m`:'已完成';
   if(round&&$('rhythmDialog').open){round.clock+=dt;round.cursor=.5+Math.sin(round.clock*2.3)*.49;$('rhythmNeedle').style.left=round.cursor*100+'%';if(round.wait>0){round.wait-=dt;round.flight+=dt;const a=Math.min(round.flight/1.1,1);ball.position.set(74+4*a,1.8+1.8*a+Math.sin(a*Math.PI)*3.4,35-3.25*a+(round.good?0:1.3*a));if(round.wait<=0){ball.visible=false;$('shootBtn').disabled=false;if(round.shots.length===3)rhythmDone();}}}
   if(lastSave>8&&api.started()&&!photo){lastSave=0;save();}
  },
  state:()=>({chapter:state.chapterId,completed:state.completed,pages:[...state.collectedItemIds],rhythmBest:state.rhythmBest,photo:!!state.springPhoto,ending:state.endingChoice,target:target(),npcs:actors.map(a=>({id:a.data.id,position:a.root.position.toArray()})),rhythm:round?{attempts:round.shots.length,cursor:round.cursor,waiting:round.wait>0}:null})
 };
}
